"""RoboWits limited-mode control session for hold_cup.
Run this file for a single persistent client; feed JSON commands on stdin.
"""
import json, sys
import numpy as np
from PIL import Image
from rcb_client import Robot

r = Robot()

def save_images(result, tag):
    for cam, img in result.last.items():
        Image.fromarray(np.ascontiguousarray(img)).save(f'/app/runs/{tag}_{cam}.jpg', quality=94)

def report(result):
    p = result.meta.get('proprio') or {}
    print(json.dumps({'meta': result.meta, 'proprio': p.get('now'), 'plan': result.meta.get('plan'), 'clipped': result.meta.get('clipped')}), flush=True)

obs = r.get_obs(video='none')
save_images(obs, 'initial')
print(json.dumps({'ready': True, 'spec': r.spec(), 'meta': obs.meta}), flush=True)

for line in sys.stdin:
    try:
        cmd = json.loads(line)
        op = cmd['op']
        if op == 'obs':
            out = r.get_obs(video='none')
            save_images(out, cmd.get('tag','obs'))
            report(out)
        elif op == 'watch':
            out = r.get_obs(seconds=float(cmd['seconds']), video='frames', video_fps=int(cmd.get('fps',10)))
            save_images(out, cmd.get('tag','watch'))
            report(out)
        elif op in ('ee','joint'):
            kwargs = {'video': cmd.get('video','none'), 'note':cmd.get('note','')}
            if 'dt' in cmd: kwargs['dt'] = float(cmd['dt'])
            out = r.submit('ee_pose' if op=='ee' else 'joint_position', np.array(cmd['actions'],dtype=np.float32), **kwargs)
            save_images(out, cmd.get('tag','action'))
            report(out)
        elif op == 'status':
            print(json.dumps(r.status()), flush=True)
        elif op == 'save':
            out = r.get_obs(video='none')
            out.save(cmd.get('path','/app/runs/final'))
            report(out)
        elif op == 'quit':
            print(json.dumps({'quit':True}),flush=True); break
        else:
            print(json.dumps({'error':'unknown op'}), flush=True)
    except Exception as e:
        print(json.dumps({'error':repr(e)}), flush=True)
